# frozen_string_literal: true

# Generates the edits corpus (spec 8.1): IniFile as the providers drive it, on
# the calls every release has.
#
#   RUBYLIB=<release>/lib ruby edits.rb > edits-<release>.json     (see gen.sh)
require_relative 'edits_harness'

BASIC = "[a]\nx = 1\ny = 2\n\n[b]\nz = 3\n"

# Section-only and setting reads on the shapes of file the providers meet.
add('read-basic', BASIC, [['section_names'], ['section?', 'a'], ['section?', 'c'], ['get_value', 'a', 'x'], ['get_value', 'a', 'q'],
                          ['get_value', 'c', 'x'], ['get_value', 'a', nil], ['get_value', '', 'x']])
add('read-empty-file', '', [['section_names'], ['section?', ''], ['get_value', '', 'x']])
