add('read-directory', :directory, [['section_names'], ['get_value', 'a', 'x']])
add('directory-save-fails', :directory, section_only_create('a'))
add('missing-parent-create', :missing_parent, setting_create('a', 'x', ['1']))
add('read-global-section', "g = 1\n[a]\nx = 1\n", [['section_names'], ['get_value', '', 'g'], ['get_value', 'a', 'g']])

